      "id": "gwcs-stockholm-lordagstur-trosa-2026-06-13",
      "name": "Lördagstur till Trosa",
      "date": "2026-06-13",
      "dateEnd": "2026-06-13",
      "time": "09:30",
      "type": "Körning",
      "region": "Stockholm",
